$(document).ready(function () {

    var baseUrl = window.location.origin;
    let retrive_data = baseUrl + '/seva_pooja_report_ajax';

    let grandTotal = 0;

    loadTable();

    // ================== ✅ FILTER ==================
    $('.submit_seva_pooja_report').click(function () {

        var from_date = $('.from_date').val();
        var to_date = $('.to_date').val();
        var financial_year = $('.financial_year option:selected').text();

        if (!from_date || !to_date || !financial_year) {
            alert("Please select all fields");
            return;
        }

        var yearParts = financial_year.split('-');
        var startYear = yearParts[0];
        var endYear = yearParts[1];

        // Safe Date
        var fy_start = new Date(startYear, 3, 1);  // April
        var fy_end = new Date(endYear, 2, 31);     // March

        var from = new Date(from_date);
        var to = new Date(to_date);

        if (from < fy_start || to > fy_end) {
            alert("Select date within the financial year");
            return;
        }

        if (from > to) {
            alert("From date should not be greater than To date");
            return;
        }

        loadTable();
    });

    // ================== ✅ DATATABLE ==================
    function loadTable() {

        $('#seva_pooja_report').DataTable({
            processing: true,
            serverSide: true,
            destroy: true,
            scrollY: 500,
            scrollX: true,
            scrollCollapse: true,
            dom: 'Bfrtip',

            buttons: [

                // ================== EXCEL ==================
                {
                    extend: 'excelHtml5',
                    text: 'Export to Excel',
                    filename: 'Seva_Pooja_Report',

                    action: function (e, dt, button, config) {
                        var self = this;

                        dt.one('preXhr', function (e, s, data) {
                            data.length = -1;
                        });

                        dt.one('draw', function () {

                            $.fn.dataTable.ext.buttons.excelHtml5.action.call(self, e, dt, button, config);

                            dt.one('preXhr', function (e, s, data) {
                                data.length = 10;
                            });

                            setTimeout(function () {
                                dt.ajax.reload();
                            }, 100);
                        });

                        dt.ajax.reload();
                    },

                    customize: function (xlsx) {

                        var sheet = xlsx.xl.worksheets['sheet1.xml'];
                        var sheetData = $('sheetData', sheet);

                        var from_date = $('.from_date').val() || '';
                        var to_date = $('.to_date').val() || '';
                        var financial_year = $('.financial_year option:selected').text() || '';

                        $('c[r=A1] t', sheet).text('Seva Pooja Report');

                        var lastRow = $('sheetData row', sheet).length + 1;

                        sheetData.append(`
                            <row r="${lastRow}">
                                <c t="inlineStr" s="2" r="E${lastRow}">
                                    <is><t>Grand Total</t></is>
                                </c>
                                <c t="n" s="2" r="F${lastRow}">
                                    <v>${parseFloat(grandTotal || 0).toFixed(2)}</v>
                                </c>
                            </row>
                        `);
                    }
                },

                // ================== PDF ==================
                {
                    extend: 'pdfHtml5',
                    text: 'Export to PDF',
                    filename: 'Seva_Pooja_Report',

                    customize: function (doc) {

                        var from_date = $('.from_date').val() || '';
                        var to_date = $('.to_date').val() || '';
                        var financial_year = $('.financial_year option:selected').text() || '';

                        doc.content.splice(0, 0, {
                            text: 'Seva Pooja Report',
                            fontSize: 14,
                            alignment: 'center',
                            bold: true,
                            margin: [0, 0, 0, 10]
                        });

                        doc.content.push({
                            text: 'Grand Total: ₹ ' + parseFloat(grandTotal || 0).toFixed(2),
                            margin: [0, 10, 0, 5],
                            bold: true,
                            alignment: 'center'
                        });

                        doc.content.push({
                            text: `From: ${from_date}   To: ${to_date}   FY: ${financial_year}`,
                            margin: [0, 5, 0, 0],
                            alignment: 'left'
                        });
                    }
                }
            ],

            ajax: {
                url: retrive_data,
                data: function (d) {
                    d.from_date = $('.from_date').val();
                    d.to_date = $('.to_date').val();
                    d.financial_year = $('.financial_year').val();
                    d.payment_type = $('.payment_type').val();
                },
                dataSrc: function (json) {
                    grandTotal = json.grand_total || 0;
                    return json.data;
                }
            },

            columns: [
                {
                    data: null,
                    render: function (data, type, row, meta) {
                        return meta.row + 1;
                    }
                },
                { data: "receipt_no" },
                { data: "receipt_date" },
                { data: "customer_name" },
                { data: "payment_type" },
                { data: "grand_total" },

                {
                    title: 'Edit',
                    render: function (data, type, full) {
                        if (canEdit) {
                        return `<a href='/sevapooja/edit_sevapooja/${full.id}'><i class="ti-pencil-alt"></i></a>`;
                        }else
                        {
                            return '';
                        }
                    }
                },

                {
                    title: 'Print',
                    render: function (data, type, full) {
                        return `<a href="#" onclick="window.open('/print-receipt/${full.id}', '_blank'); return false;">
                                    <i class="ti-printer"></i>
                                </a>`;
                    }
                },

                {
                    title: 'View',
                    render: function (data, type, full) {
                        return `<a href="#" class="view-btn" data-id="${full.id}">
                                    <i class="ti-eye"></i>
                                </a>`;
                    }
                }
            ],

            // ✅ FIXED FOOTER
            footerCallback: function () {
                var api = this.api();
                var json = api.ajax.json();

                if (json && json.grand_total) {
                    $(api.column(4).footer())
                        .html('₹ ' + parseFloat(json.grand_total).toFixed(2));
                }
            }
        });
    }

    // ================== ✅ VIEW MODAL ==================
    $(document).on('click', '.view-btn', function (e) {
        e.preventDefault();

        let id = $(this).data('id');

        $.ajax({
            url: '/get-pooja-details/' + id,
            type: 'GET',
            success: function (data) {

                let html = '';
                let total = 0;

                data.forEach(function (item) {
                    total += parseFloat(item.total);

                    html += `
                        <tr>
                            <td>${item.pooja_name}</td>
                            <td>${item.qty}</td>
                            <td>${item.total}</td>
                        </tr>
                    `;
                });

                html += `
                    <tr>
                        <td colspan="2"><b>Total</b></td>
                        <td><b>${total}</b></td>
                    </tr>
                `;

                $('#viewTableBody').html(html);

                $('#viewModal').modal('show');
            }
        });
    });

});